//! Data model for the shared NextTouch device/firmware catalog.
//!
//! The catalog is generated by `tools/gen_catalog.py` from the ipsw.me API
//! (firmware URLs + SHA-256) plus curated device/SoC/status data, and is
//! bundled identically by the desktop (Rust/egui), Android (Kotlin/Compose)
//! and iOS (SwiftUI) apps. See `assets/catalog.json` and the schema string
//! [`SCHEMA`].
//!
//! Honesty rule (project-wide): a firmware's `status` is only ever
//! `Tested`/`TestedSlow`/`Experimental` for the legacy range the baseline
//! qemu-ios engine implements. Every iOS 8/9/10 entry is `NotBootingYet`
//! until a future engine release proves otherwise — the picker must never
//! claim one boots.

use serde::{Deserialize, Serialize};

/// The schema identifier written into every generated catalog.json.
pub const SCHEMA: &str = "nexttouch-catalog/1";

/// The embedded catalog, generated at build-prep time by tools/gen_catalog.py.
pub const EMBEDDED_CATALOG_JSON: &str = include_str!("../assets/catalog.json");

/// Boot-support status of one firmware on the current engine.
///
/// Serialized in snake_case to match catalog.json exactly.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum FirmwareStatus {
    /// Boots to the home screen and shuts down cleanly on the baseline
    /// engine (LightTouch compatibility ladder: reaches `clean`).
    Tested,
    /// Tested on the baseline engine, but noticeably slow.
    TestedSlow,
    /// Can be prepared and tried on the baseline engine; not yet checked.
    Experimental,
    /// The engine cannot boot this yet (all iOS 8/9/10 entries in v0.1.0).
    NotBootingYet,
}

impl FirmwareStatus {
    /// Short human label for pickers.
    pub fn label(&self) -> &'static str {
        match self {
            FirmwareStatus::Tested => "Tested",
            FirmwareStatus::TestedSlow => "Tested, slow",
            FirmwareStatus::Experimental => "Experimental",
            FirmwareStatus::NotBootingYet => "Not booting yet",
        }
    }

    /// Whether the current engine can run this firmware at all.
    pub fn is_runnable(&self) -> bool {
        !matches!(self, FirmwareStatus::NotBootingYet)
    }
}

/// Development tier of a device — a priority label, never a boot claim.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum DeviceTier {
    /// Supported by the baseline engine today.
    Legacy,
    /// A5 family: the first iOS 8/9 development target.
    Target,
    /// A6 family: the second target (32-bit path to iOS 10).
    Experimental,
    /// arm64 family (A7+): future work, also needs a Secure Enclave model.
    Future,
}

impl DeviceTier {
    pub fn label(&self) -> &'static str {
        match self {
            DeviceTier::Legacy => "Legacy (engine-supported)",
            DeviceTier::Target => "Target (A5 — in development)",
            DeviceTier::Experimental => "Experimental (A6 — planned)",
            DeviceTier::Future => "Future (arm64 — planned)",
        }
    }
}

/// Internal engineering stage of a firmware on the engine roadmap
/// (Claude blueprint): a finer ladder behind the three user-facing
/// picker labels. `stage` reaching `Springboard` or beyond requires a
/// recorded M1–M6 boot-test result (see docs/ROADMAP.md); v0.1.0 carries
/// every iOS 8/9/10 entry at `Planned`, and legacy entries at the stage
/// the baseline engine has proven for them.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Stage {
    Planned,
    Skeleton,
    Kernel,
    Userland,
    Springboard,
    Usable,
    Qualified,
}

impl Stage {
    pub fn label(&self) -> &'static str {
        match self {
            Stage::Planned => "planned",
            Stage::Skeleton => "skeleton",
            Stage::Kernel => "kernel",
            Stage::Userland => "userland",
            Stage::Springboard => "springboard",
            Stage::Usable => "usable",
            Stage::Qualified => "qualified",
        }
    }
}

/// One firmware release for a device.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct FirmwareEntry {
    /// LightTouch-style id: `<board>-<build>` (e.g. `n94ap-12H321`).
    /// Null only on placeholder entries the source did not confirm.
    pub id: Option<String>,
    /// Version string, e.g. `8.4.1`. Null on unconfirmed placeholders.
    pub version: Option<String>,
    /// Apple build id, e.g. `12H321`.
    pub build: Option<String>,
    /// `iPhone OS` for majors < 4, otherwise `iOS`.
    pub os_name: Option<String>,
    /// Major version number (8, 9, 10, ...).
    pub ios_major: Option<u32>,
    /// IPSW file name as served by Apple.
    pub ipsw_filename: Option<String>,
    /// Direct Apple download URL (from ipsw.me). The only host family the
    /// apps may ever download firmware from.
    pub download_url: Option<String>,
    /// SHA-256 of the IPSW as published by ipsw.me. Null when the source
    /// does not publish one — see `sha256_note`. Never fabricated.
    pub sha256: Option<String>,
    /// Why `sha256` is null, when it is.
    pub sha256_note: Option<String>,
    /// Whether Apple still signs this firmware (informational only).
    pub signed: Option<bool>,
    /// Honest boot-support status. See [`FirmwareStatus`].
    pub status: FirmwareStatus,
    /// Internal engineering stage. See [`Stage`].
    pub stage: Stage,
}

impl FirmwareEntry {
    /// True when the download URL is present and on an Apple host.
    pub fn url_is_apple_host(&self) -> bool {
        match &self.download_url {
            Some(u) => is_apple_download_host(u),
            None => false,
        }
    }

    /// True when the entry carries both a URL and a SHA-256, i.e. a
    /// download-then-verify cycle is possible.
    pub fn is_downloadable_verified(&self) -> bool {
        self.download_url.is_some() && self.sha256.is_some() && self.url_is_apple_host()
    }
}

/// One emulated device and its firmwares.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct Device {
    /// Apple product identifier, e.g. `iPhone4,1`.
    pub identifier: String,
    /// Marketing name, e.g. `iPhone 4S`.
    pub name: String,
    /// Board config, lower-case, e.g. `n94ap`.
    pub board: String,
    /// SoC marketing name, e.g. `A5`.
    pub soc: String,
    /// SoC chip id, e.g. `S5L8940`.
    pub soc_chip: String,
    /// Guest CPU architecture: `armv6`, `armv7`, `armv7s` or `arm64`.
    pub arch: String,
    /// Native display resolution `[width, height]` in pixels.
    pub display_px: [u32; 2],
    /// RAM in MiB.
    pub ram_mb: u32,
    pub tier: DeviceTier,
    /// Part of the picker's quick-start defaults.
    pub quick_start: bool,
    pub firmwares: Vec<FirmwareEntry>,
}

/// The catalog file as a whole.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct Catalog {
    pub schema: String,
    pub catalog_version: u32,
    /// Generation timestamp (UTC, ISO-8601) recorded by the generator.
    pub generated_at_utc: String,
    pub generated_by: String,
    /// Where the data came from (URLs + curation note).
    pub source: String,
    /// True only when every entry was fetched live and verified complete.
    pub verified: bool,
    /// Quick-start picks as `<identifier>:<version>` strings.
    pub quick_start: Vec<String>,
    pub devices: Vec<Device>,
}

impl Catalog {
    /// Parse a catalog from JSON text.
    pub fn from_json(text: &str) -> Result<Catalog, serde_json::Error> {
        serde_json::from_str(text)
    }

    /// Load the catalog embedded at build time.
    pub fn embedded() -> Catalog {
        Catalog::from_json(EMBEDDED_CATALOG_JSON)
            .expect("embedded catalog.json must always parse; it is generated and tested")
    }

    pub fn device(&self, identifier: &str) -> Option<&Device> {
        self.devices.iter().find(|d| d.identifier == identifier)
    }

    /// Resolve the quick-start list to (device, firmware) pairs, in order.
    pub fn quick_start_entries(&self) -> Vec<(&Device, &FirmwareEntry)> {
        let mut out = Vec::new();
        for key in &self.quick_start {
            if let Some((ident, version)) = key.split_once(':') {
                if let Some(d) = self.device(ident) {
                    if let Some(f) = d
                        .firmwares
                        .iter()
                        .find(|f| f.version.as_deref() == Some(version))
                    {
                        out.push((d, f));
                    }
                }
            }
        }
        out
    }

    /// Case-insensitive search over device names, identifiers, boards, SoCs.
    pub fn search_devices(&self, query: &str) -> Vec<&Device> {
        let q = query.trim().to_lowercase();
        if q.is_empty() {
            return self.devices.iter().collect();
        }
        self.devices
            .iter()
            .filter(|d| {
                d.name.to_lowercase().contains(&q)
                    || d.identifier.to_lowercase().contains(&q)
                    || d.board.contains(&q)
                    || d.soc.to_lowercase().contains(&q)
                    || d.soc_chip.to_lowercase().contains(&q)
            })
            .collect()
    }
}

/// Privacy rule (DeepSeek audit): firmware downloads may only ever go to
/// Apple hosts. This is the single allow-list every platform enforces.
pub fn is_apple_download_host(url: &str) -> bool {
    let host = url
        .split("://")
        .nth(1)
        .unwrap_or("")
        .split(['/', '?', '#', ':'])
        .next()
        .unwrap_or("")
        .to_lowercase();
    host == "apple.com"
        || host.ends_with(".apple.com")
        || host == "cdn-apple.com"
        || host.ends_with(".cdn-apple.com")
}
